const meStatus = c => c.status === 'vencido' ? `<span class="pill crit">VENCIDO desde ${ddmm(c.vencimento)}</span>` : c.status === 'vence' ? `<span class="pill warn">Vence ${c.dias === 0 ? 'hoje' : `em ${c.dias} dia(s)`} · ${ddmm(c.vencimento)}</span>` : c.status === 'em_dia' ? `<span class="pill ok">Em dia até ${ddmm(c.vencimento)}</span>` : '<span class="pill neutral">Sem fatura em aberto</span>';
async function vMensalistas() {
