      ['forma', 'Forma', r => `${ME_FORMA[r.forma] || r.forma}${r.id_transacao ? `<div class="tiny muted">${esc(r.id_transacao)}</div>` : ''}`],
      ['jump', 'JUMP', r => r.status === 'renovado' ? `<span class="pill ok">Renovado</span><div class="tiny muted">${dBR(r.venc_anterior)} → ${dBR(r.venc_corrigido || r.venc_novo_jump) || '—'}${r.venc_corrigido ? ' (corrigido)' : ''}</div>${r.erro ? `<div class="tiny" style="color:var(--warn)">${esc(r.erro)}</div>` : ''}` : r.status === 'erro' ? `<span class="pill crit">Erro</span><div class="tiny" style="color:var(--crit)">${esc(r.erro || '')}</div>` : '<span class="pill neutral">Enviando</span>'],
      ['lancado', 'Lançado por', r => `${esc(r.lancado_por || '')}<div class="tiny muted">${dt(r.lancado_em)}</div>`],
