    <div id="meMsg"></div>
    <button class="primary wide" id="meSalvar">Salvar e renovar na JUMP</button></form>`;
  m.addEventListener('click', ev => { if (ev.target === m || ev.target.closest('[data-act="meFechar"]')) m.remove(); });
  document.body.appendChild(m);
  document.getElementById('fMe').onsubmit = ev => { ev.preventDefault(); meEnviar(c); };
}
function meMaisMes(d) { if (!d) return ''; const [y, mo, da] = d.split('-').map(Number); const ult = new Date(Date.UTC(y, mo + 1, 0)).getUTCDate(); return new Date(Date.UTC(y, mo, Math.min(da, ult))).toISOString().slice(0, 10); }
async function meArquivo(f) {
  if (f.type === 'application/pdf') {
    if (f.size > 2000000) throw new Error('PDF grande demais (máximo 2 MB).');
    return await new Promise((r, j) => { const fr = new FileReader(); fr.onload = () => r(fr.result); fr.onerror = () => j(new Error('Não consegui ler o PDF.')); fr.readAsDataURL(f); });
  }
  const url = URL.createObjectURL(f);
  try {
    const img = await new Promise((r, j) => { const i = new Image(); i.onload = () => r(i); i.onerror = () => j(new Error('Não consegui ler a foto do comprovante.')); i.src = url; });
    const k = Math.min(1, 1600 / Math.max(img.width, img.height)), cv = document.createElement('canvas');
    cv.width = Math.round(img.width * k); cv.height = Math.round(img.height * k); cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
    return cv.toDataURL('image/jpeg', 0.78);
  } finally { URL.revokeObjectURL(url); }
}
async function meEnviar(c) {
  const msg = document.getElementById('meMsg'), b = document.getElementById('meSalvar');
  const err = t => { msg.innerHTML = `<div class="msg err">${esc(t)}</div>`; b.disabled = false; b.textContent = 'Salvar e renovar na JUMP'; };
  const f = (document.getElementById('meComp').files || [])[0]; if (!f) return err('Anexe o comprovante.');
  const valor = Number(String(document.getElementById('meValor').value).replace(/\./g, '').replace(',', '.'));
  if (!(valor > 0)) return err('Informe o valor pago.');
  const forma = document.getElementById('meForma').value; if (!forma) return err('Escolha a forma de pagamento.');
  if (valor !== num(c.valor) && !confirm(`O valor pago (${brl(valor)}) é diferente da mensalidade (${brl(c.valor)}). A renovação será feita e o pagamento fica como ponto de conferência. Continuar?`)) return;
  b.disabled = true; b.textContent = 'Renovando na JUMP…';
  try {
    const comprovante = await meArquivo(f);
    const { data, error } = await sb.functions.invoke('mensalistas', { body: { acao: 'pagar', client_id: c.client_id, valor, forma, pago_em: document.getElementById('meQuando').value,
      pagante: document.getElementById('mePag').value, placa: document.getElementById('mePlaca').value, id_transacao: document.getElementById('meTx').value, comprovante } });
    let r = data;
    if (error) { try { r = await error.context.json(); } catch (e) { r = { erro: erroAmigavel(error) }; } }
    if (!r || !r.ok) return err((r && r.erro) || 'Não foi possível registrar.');
    document.getElementById('mMe').remove();
    carimbo('RENOVADO', `${c.nome} · próximo vencimento ${ddmm(r.proximo_vencimento || '')}`, true);
    S.msg = [r.aviso ? 'warn' : 'ok', `Pagamento de ${c.nome} registrado e renovado na JUMP. Próximo vencimento: ${dBR(r.proximo_vencimento || '')}${r.corrigido ? ` (a JUMP tinha marcado ${dBR(r.vencimento_jump)} e o app corrigiu para manter o dia do vencimento)` : ''}.${r.divergencia_valor ? ` Valor diferente do esperado (${brl(r.valor_esperado)}): ponto de conferência.` : ''}${r.aviso ? ' ' + r.aviso : ''}`];
    render();
  } catch (e) { err(erroAmigavel(e)); }
}
